import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007;

    static long fastExponentiation(long base, long exponent) {
        long result = 1;
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            exponent >>= 1;
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long K = sc.nextLong();

        if (K == 0) {
            System.out.println(fastExponentiation(p, p - 1));
            return;
        }
        if (K == 1) {
            System.out.println(fastExponentiation(p, p));
            return;
        }

        boolean[] visited = new boolean[(int) p];
        int cycleCount = 0;

        for (int i = 0; i < p; i++) {
            if (visited[i]) continue;
            int size = 0;
            long current = i;
            while (!visited[(int) current]) {
                size++;
                visited[(int) current] = true;
                current = (current * K) % p;
            }
            if (size > 1) cycleCount++;
        }

        System.out.println(fastExponentiation(p, cycleCount));
    }
}
